     1→#!/usr/bin/env bun
     2→
     3→/**
     4→ * CreateDynamicCore.ts - Assembles SKILL.md from Components/
     5→ *
     6→ * Usage: bun ~/.claude/skills/PAI/Tools/CreateDynamicCore.ts
     7→ *
     8→ * Reads all .md files from Components/, sorts by numeric prefix,
     9→ * concatenates them, and writes to SKILL.md with build timestamp
    10→ */
    11→
    12→import { readdirSync, readFileSync, writeFileSync } from "fs";
    13→import { join } from "path";
    14→
    15→const HOME = process.env.HOME!;
    16→const CORE_DIR = join(HOME, ".claude/skills/PAI");
    17→const COMPONENTS_DIR = join(CORE_DIR, "Components");
    18→const ALGORITHM_DIR = join(COMPONENTS_DIR, "Algorithm");
    19→const OUTPUT_FILE = join(CORE_DIR, "SKILL.md");
    20→const SETTINGS_PATH = join(HOME, ".claude/settings.json");
    21→
    22→/**
    23→ * Load identity variables from settings.json for template resolution
    24→ */
    25→function loadVariables(): Record<string, string> {
    26→  try {
    27→    const settings = JSON.parse(readFileSync(SETTINGS_PATH, "utf-8"));
    28→    return {
    29→      "{DAIDENTITY.NAME}": settings.daidentity?.name || "PAI",
    30→      "{DAIDENTITY.FULLNAME}": settings.daidentity?.fullName || "Personal AI",
    31→      "{DAIDENTITY.DISPLAYNAME}": settings.daidentity?.displayName || "PAI",
    32→      "{PRINCIPAL.NAME}": settings.principal?.name || "User",
    33→      "{PRINCIPAL.TIMEZONE}": settings.principal?.timezone || "UTC",
    34→    };
    35→  } catch {
    36→    console.warn("⚠️ Could not read settings.json, using defaults");
    37→    return {
    38→      "{DAIDENTITY.NAME}": "PAI",
    39→      "{DAIDENTITY.FULLNAME}": "Personal AI",
    40→      "{DAIDENTITY.DISPLAYNAME}": "PAI",
    41→      "{PRINCIPAL.NAME}": "User",
    42→      "{PRINCIPAL.TIMEZONE}": "UTC",
    43→    };
    44→  }
    45→}
    46→
    47→/**
    48→ * Resolve template variables in content
    49→ */
    50→function resolveVariables(content: string, variables: Record<string, string>): string {
    51→  let result = content;
    52→  for (const [key, value] of Object.entries(variables)) {
    53→    result = result.replaceAll(key, value);
    54→  }
    55→  return result;
    56→}
    57→
    58→// Generate timestamp in format: DAY MONTH YEAR HOUR MINUTE SECOND
    59→function getTimestamp(): string {
    60→  const now = new Date();
    61→  const day = now.getDate();
    62→  const months = ['January', 'February', 'March', 'April', 'May', 'June',
    63→                  'July', 'August', 'September', 'October', 'November', 'December'];
    64→  const month = months[now.getMonth()];
    65→  const year = now.getFullYear();
    66→  const hour = now.getHours().toString().padStart(2, '0');
    67→  const minute = now.getMinutes().toString().padStart(2, '0');
    68→  const second = now.getSeconds().toString().padStart(2, '0');
    69→
    70→  return `${day} ${month} ${year} ${hour}:${minute}:${second}`;
    71→}
    72→
    73→// Load versioned algorithm
    74→function loadAlgorithm(): string {
    75→  const latestFile = join(ALGORITHM_DIR, "LATEST");
    76→  const version = readFileSync(latestFile, "utf-8").trim();
    77→  const algorithmFile = join(ALGORITHM_DIR, `${version}.md`);
    78→  return readFileSync(algorithmFile, "utf-8");
    79→}
    80→
    81→// Get all .md files, sorted by numeric prefix
    82→const components = readdirSync(COMPONENTS_DIR)
    83→  .filter(f => f.endsWith(".md"))
    84→  .sort((a, b) => {
    85→    const numA = parseInt(a.split("-")[0]) || 0;
    86→    const numB = parseInt(b.split("-")[0]) || 0;
    87→    return numA - numB;
    88→  });
    89→
    90→if (components.length === 0) {
    91→  console.error("❌ No component files found in Components/");
    92→  process.exit(1);
    93→}
    94→
    95→// Assemble content
    96→let output = "";
    97→const timestamp = getTimestamp();
    98→const algorithmContent = loadAlgorithm();
    99→
   100→for (const file of components) {
   101→  let content = readFileSync(join(COMPONENTS_DIR, file), "utf-8");
   102→
   103→  // Inject timestamp into frontmatter component
   104→  if (file === "00-frontmatter.md") {
   105→    content = content.replace(
   106→      "  Build:  bun ~/.claude/skills/PAI/Tools/CreateDynamicCore.ts",
   107→      `  Build:  bun ~/.claude/skills/PAI/Tools/CreateDynamicCore.ts\n  Built:  ${timestamp}`
   108→    );
   109→  }
   110→
   111→  // Inject versioned algorithm
   112→  if (content.includes("{{ALGORITHM_VERSION}}")) {
   113→    content = content.replace("{{ALGORITHM_VERSION}}", algorithmContent);
   114→  }
   115→
   116→  output += content;
   117→
   118→  // No extra newlines - components manage their own spacing
   119→}
   120→
   121→// Resolve template variables from settings.json
   122→const variables = loadVariables();
   123→output = resolveVariables(output, variables);
   124→
   125→// Write output
   126→writeFileSync(OUTPUT_FILE, output);
   127→
   128→const resolvedCount = Object.entries(variables)
   129→  .filter(([key]) => output.includes(key) === false)
   130→  .length;
   131→
   132→console.log(`✅ Built SKILL.md from ${components.length} components:`);
   133→components.forEach((c, i) => {
   134→  console.log(`   ${(i + 1).toString().padStart(2)}. ${c}`);
   135→});
   136→console.log(`\n🔄 Resolved ${Object.keys(variables).length} template variables:`);
   137→for (const [key, value] of Object.entries(variables)) {
   138→  console.log(`   ${key} → ${value}`);
   139→}
   140→console.log(`\n📄 Output: ${OUTPUT_FILE}`);
   141→

