/**
 * Lead Reactivation Worker
 *
 * Cloudflare Worker that replaces n8n workflows for lead reactivation calling.
 *
 * Endpoints:
 *   GET  /api/health       - Health check
 *   POST /api/import       - Import leads (requires API key)
 *   POST /webhook/retell   - Retell webhook callback
 *
 * Cron: Every 15 minutes - Schedule calls
 */

import type { Env } from './lib/types';
import { handleHealthCheck } from './handlers/health';
import { handleLeadImport } from './handlers/import';
import { handleRetellWebhook } from './handlers/webhook';
import { handleSkyvernCallback } from './handlers/skyvern-callback';
import { handleScheduledCalls, logSchedulerResult } from './handlers/scheduler';

export default {
  /**
   * Handle HTTP requests
   */
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const path = url.pathname;
    const method = request.method;

    // CORS preflight
    if (method === 'OPTIONS') {
      return new Response(null, {
        headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
          'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        },
      });
    }

    // Route requests
    try {
      // Health check
      if (path === '/api/health' && method === 'GET') {
        return await handleHealthCheck(env);
      }

      // Lead import
      if (path === '/api/import' && method === 'POST') {
        return await handleLeadImport(request, env);
      }

      // Retell webhook
      if (path === '/webhook/retell' && method === 'POST') {
        return await handleRetellWebhook(request, env);
      }

      // Skyvern callback webhook
      if (path === '/webhook/skyvern' && method === 'POST') {
        return await handleSkyvernCallback(request, env);
      }

      // Manual test trigger (GET for easy browser access)
      if (path === '/api/test-call' && (method === 'GET' || method === 'POST')) {
        console.log('Manual test call triggered');
        const result = await handleScheduledCalls(env);
        logSchedulerResult(result);
        return new Response(JSON.stringify(result, null, 2), {
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // 404 for unknown routes
      return new Response(
        JSON.stringify({
          error: 'Not found',
          path,
          availableEndpoints: [
            'GET /api/health',
            'POST /api/import',
            'POST /webhook/retell',
            'POST /webhook/skyvern',
          ],
        }),
        {
          status: 404,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    } catch (error) {
      console.error('Unhandled error:', error);
      return new Response(
        JSON.stringify({
          error: 'Internal server error',
          message: String(error),
        }),
        {
          status: 500,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
  },

  /**
   * Handle cron triggers (every 15 minutes)
   */
  async scheduled(event: ScheduledEvent, env: Env, ctx: ExecutionContext): Promise<void> {
    console.log(`Cron triggered at ${new Date(event.scheduledTime).toISOString()}`);

    try {
      const result = await handleScheduledCalls(env);
      logSchedulerResult(result);
    } catch (error) {
      console.error('Cron handler error:', error);
    }
  },
};

