content.content:
     1→/**
     2→ * Skyvern booking trigger integration
     3→ * Triggers browser automation to book tours on the calendar
     4→ * Ported from End Of Call - Multicentre n8n workflow
     5→ */
     6→
     7→import type { Env } from '../lib/types';
     8→
     9→export interface SkyvernBookingPayload {
    10→  action: 'book_tour';
    11→  lead_id: string;
    12→  centre_id: string;
    13→  first_name: string;
    14→  last_name: string;
    15→  phone: string;
    16→  email: string;
    17→  calendar_url: string;
    18→  selected_slot: string;
    19→  call_summary: string;
    20→  tour_date?: string;
    21→  tour_time?: string;
    22→  child_name?: string;
    23→  child_birth_year?: number;
    24→}
    25→
    26→export interface DateValidationResult {
    27→  valid_date: boolean;
    28→  reason: string;
    29→  parsed_date: string | null;
    30→  original: string;
    31→}
    32→
    33→/**
    34→ * Validates a tour date string
    35→ * Ported from End Of Call - Multicentre deterministic validation
    36→ */
    37→export function validateTourDate(dateStr: string | undefined | null): DateValidationResult {
    38→  if (!dateStr || dateStr.toString().trim() === '') {
    39→    return { valid_date: false, reason: 'empty', parsed_date: null, original: dateStr || '' };
    40→  }
    41→
    42→  const input = dateStr.toString().trim().toLowerCase();
    43→  const original = dateStr;
    44→
    45→  // Month names and abbreviations
    46→  const months = [
    47→    'january', 'february', 'march', 'april', 'may', 'june',
    48→    'july', 'august', 'september', 'october', 'november', 'december',
    49→    'jan', 'feb', 'mar', 'apr', 'jun', 'jul', 'aug', 'sep', 'sept', 'oct', 'nov', 'dec'
    50→  ];
    51→
    52→  // Day names (alone are NOT valid)
    53→  const dayNames = [
    54→    'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday',
    55→    'mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'
    56→  ];
    57→
    58→  // Invalid vague terms
    59→  const vagueTerms = ['soon', 'later', 'next week', 'sometime', 'asap', 'whenever', 'tbd', 'not sure'];
    60→
    61→  // Check for vague terms
    62→  for (const term of vagueTerms) {
    63→    if (input === term || input.includes(term)) {
    64→      return { valid_date: false, reason: 'vague_term', parsed_date: null, original };
    65→    }
    66→  }
    67→
    68→  // Check if it's ONLY a day name (invalid)
    69→  for (const day of dayNames) {
    70→    if (input === day) {
    71→      return { valid_date: false, reason: 'day_only', parsed_date: null, original };
    72→    }
    73→  }
    74→
    75→  // Pattern 1: Month name + day number (e.g., "November 28", "Nov 28th")
    76→  const monthDayPattern = new RegExp(`(${months.join('|')})\\s+(\\d{1,2})(?:st|nd|rd|th)?`, 'i');
    77→  if (input.match(monthDayPattern)) {
    78→    return { valid_date: true, reason: 'month_day_format', parsed_date: dateStr, original };
    79→  }
    80→
    81→  // Pattern 2: Day number + month name (e.g., "28 November", "28th of November")
    82→  const dayMonthPattern = new RegExp(`(\\d{1,2})(?:st|nd|rd|th)?\\s+(?:of\\s+)?(${months.join('|')})`, 'i');
    83→  if (input.match(dayMonthPattern)) {
    84→    return { valid_date: true, reason: 'day_month_format', parsed_date: dateStr, original };
    85→  }
    86→
    87→  // Pattern 3: Numeric dates (e.g., "12/25", "12-25", "12/25/2024")
    88→  const numericPattern = /^(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?$/;
    89→  const numericMatch = input.match(numericPattern);
    90→  if (numericMatch) {
    91→    const month = parseInt(numericMatch[1]);
    92→    const day = parseInt(numericMatch[2]);
    93→    if (month >= 1 && month <= 12 && day >= 1 && day <= 31) {
    94→      return { valid_date: true, reason: 'numeric_format', parsed_date: dateStr, original };
    95→    }
    96→  }
    97→
    98→  // Pattern 4: ISO format (e.g., "2024-12-25")
    99→  const isoPattern = /^(\d{4})-(\d{2})-(\d{2})$/;
   100→  if (input.match(isoPattern)) {
   101→    return { valid_date: true, reason: 'iso_format', parsed_date: dateStr, original };
   102→  }
   103→
   104→  // Pattern 5: Day name + date (e.g., "Saturday, November 28")
   105→  const dayDatePattern = new RegExp(`(?:${dayNames.join('|')})[,\\s]+.*(${months.join('|')})\\s+(\\d{1,2})`, 'i');
   106→  if (input.match(dayDatePattern)) {
   107→    return { valid_date: true, reason: 'day_date_format', parsed_date: dateStr, original };
   108→  }
   109→
   110→  return { valid_date: false, reason: 'no_date_found', parsed_date: null, original };
   111→}
   112→
   113→/**
   114→ * Triggers Skyvern to process a booking via workflow dispatch API
   115→ * @param env - Worker environment
   116→ * @param payload - Booking data
   117→ * @returns Object with success status and any error details
   118→ */
   119→export async function triggerBooking(
   120→  env: Env,
   121→  payload: SkyvernBookingPayload
   122→): Promise<{ success: boolean; error?: string; task_id?: string }> {
   123→  // Validate tour date if provided
   124→  if (payload.tour_date) {
   125→    const dateValidation = validateTourDate(payload.tour_date);
   126→    if (!dateValidation.valid_date) {
   127→      console.warn(`Invalid tour date for lead ${payload.lead_id}: ${dateValidation.reason}`);
   128→      return {
   129→        success: false,
   130→        error: `Invalid tour date: ${dateValidation.reason} (value: ${dateValidation.original})`,
   131→      };
   132→    }
   133→  }
   134→
   135→  // Check for missing tour date/time
   136→  if (!payload.tour_date || !payload.tour_time) {
   137→    console.warn(`Missing tour date/time for lead ${payload.lead_id}`);
   138→    return {
   139→      success: false,
   140→      error: `Missing tour ${!payload.tour_date ? 'date' : 'time'}`,
   141→    };
   142→  }
   143→
   144→  // Use Skyvern API if configured, otherwise fall back to webhook
   145→  if (env.SKYVERN_API_KEY && env.SKYVERN_API_URL) {
   146→    return await triggerSkyvernAPI(env, payload);
   147→  } else if (env.SKYVERN_WEBHOOK_URL) {
   148→    return await triggerSkyvernWebhook(env, payload);
   149→  } else {
   150→    console.warn('Neither SKYVERN_API_KEY nor SKYVERN_WEBHOOK_URL configured');
   151→    return { success: false, error: 'Skyvern not configured' };
   152→  }
   153→}
   154→
   155→/**
   156→ * Triggers Skyvern via the workflow dispatch API (preferred method)
   157→ */
   158→async function triggerSkyvernAPI(
   159→  env: Env,
   160→  payload: SkyvernBookingPayload
   161→): Promise<{ success: boolean; error?: string; task_id?: string }> {
   162→  const SKYVERN_WORKFLOW_ID = 'wpid_472637885728525632'; // Code Ninjas tour booking workflow
   163→
   164→  try {
   165→    // Correct endpoint: POST /v1/run/workflows with workflow_id in body
   166→    const response = await fetch(`${env.SKYVERN_API_URL}/v1/run/workflows`, {
   167→      method: 'POST',
   168→      headers: {
   169→        'Content-Type': 'application/json',
   170→        'x-api-key': env.SKYVERN_API_KEY!,
   171→      },
   172→      body: JSON.stringify({
   173→        workflow_id: SKYVERN_WORKFLOW_ID,
   174→        // Use 'parameters' not 'data' - this overrides workflow defaults
   175→        parameters: {
